/**
 * Everything the shell can be told went wrong. Deliberately small: the shell's
 * only sensible responses are "show the message" and "carry on with the last
 * good snapshot".
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * The ledger could not be read or written. The strip on screen is still
     * valid; the mutation did not happen.
     */
    case Ledger(message: String
    )
    /**
     * A lane or pane id that is not in the ledger. Usually a stale id held by
     * the shell across a mutation it missed.
     */
    case NotFound(kind: String, id: String
    )
    /**
     * The mutation is not allowed by the model, e.g. moving a lane relative to
     * itself or nesting a lane inside a pane.
     */
    case Invalid(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Ledger(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound(
            kind: try FfiConverterString.read(from: &buf), 
            id: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Invalid(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Ledger(message):
            writeInt(&buf, Int32(1))
